{"implementation": "import math


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    if "threshold" not in case or "calls" not in case:
        raise ValueError("case missing required fields")

    threshold = case["threshold"]
    calls = case["calls"]

    if not _is_number(threshold):
        raise ValueError("threshold must be a finite number")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    accepted_call_ids = []
    diagnostics = []

    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("each call must be an object")

        required = ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable")
        for field in required:
            if field not in call:
                raise ValueError("call missing required field")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        if not _is_number(loss_without) or not _is_number(loss_with):
            raise ValueError("loss values must be finite numbers")
        if not _is_number(prediction_tokens):
            raise ValueError("prediction_tokens must be a finite number")
        if prediction_tokens < 0:
            raise ValueError("prediction_tokens must be non-negative")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")

        denominator = max(1.0, float(prediction_tokens))
        normalized_gain = (float(loss_without) - float(loss_with)) / denominator
        accepted = parseable and normalized_gain >= float(threshold)

        if accepted:
            accepted_call_ids.append(call_id)

        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": round(normalized_gain, 6),
        })

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
